var i=`0356-wiener-schnitzel`;var n=`world-0356`;var s=`AT`;var r=`western-europe`;var a=4;var l=25;var o={en:`Wiener Schnitzel`,ua:`Віденський шніцель`};var d={en:`A traditional Austria dish made with veal cutlet, all-purpose flour, chicken egg, breadcrumbs. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Австрія. Основні інгредієнти: теляча відбивна, пшеничне борошно універсальне, куряче яйце, панірувальні сухарі. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:10,i:[[`veal-cutlet`,680,`g`],[`all-purpose-flour`,95,`g`],[`chicken-egg`,2,`pcs`],[`breadcrumbs`,185,`g`],[`table-salt`,null,`to_taste`]]},{en:`Fry the breaded veal in plenty of hot clarified butter, swirling the pan so the crumb coating soufflés and turns evenly golden; do not press it down.`,ua:`Смажте запаніровану телятину у великій кількості гарячого топленого масла, похитуючи сковороду, щоб паніровка піднялася та рівномірно зарум’янилася; не притискайте.`,t:[`pan-frying`],m:13,i:[[`clarified-butter`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon`,2,`pcs`],[`parsley`,18,`g`]]}];var g={slug:i,id:n,country:`AT`,region:r,servings:4,minutes:25,title:o,text:d,steps:u};export{s as country,g as default,n as id,l as minutes,r as region,a as servings,i as slug,u as steps,d as text,o as title};